import Vue from "vue";
import Grid from "../../dashboard-common/vue/grid.vue";
import Modal from "../../dashboard-common/vue/modal.vue";
import Tile from "../../dashboard-common/vue/dashboard/tile.vue";
import Dashboard from "../../dashboard-common/vue/dashboard/index.vue";
import Pager from "../../dashboard-common/vue/pager.vue";
import Ajax from "../../dashboard-common/vue/ajax";

Vue.use(Ajax, {
  handleUnauthorized: true
});

// Setup antiforgery token interceptors
(function()
{
    var appName = "Dashboard";
    var axiosInterceptorId = null;
    var axiosResponseInterceptorId = null;
    var originalFetch = null;
    var setupInterceptors = function ()
    {
      // MooTools interceptor
      if (window.MooTools && window.Request && !window.Request._antiForgeryPatched)
      {
        var originalInitialize = Request.prototype.initialize;
        Request.prototype.initialize = function (options)
        {
          originalInitialize.apply(this, arguments);
          if (window.AntiForgeryToken && window.AntiForgeryToken !== '')
          {
            this.options.headers = this.options.headers || {};
            var method = (this.options.method || 'get').toLowerCase();
            var antiForgeryToken = window.AntiForgeryToken || "";
            if (antiForgeryToken && (method === 'post' || method === 'put' || method === 'delete'))
            {
              this.options.withCredentials = true;
              this.options.headers['__RequestVerificationToken'] = antiForgeryToken;
              console.log(appName + ": Added antiforgery token to MooTools", method.toUpperCase(), this.options.url);
            }
            else if (method === 'post' || method === 'put' || method === 'delete')
            {
              console.log(appName + ": No antiforgery token available for MooTools", method.toUpperCase(), this.options.url);
            }
          }
        };
        // Add MooTools Request response interceptor
        var originalOnSuccess = Request.prototype.onSuccess;
        var originalOnFailure = Request.prototype.onFailure;
        Request.prototype.onSuccess = function()
        {
          // Add any 401 response handlers here
          return originalOnSuccess.apply(this, arguments);
        };
        Request.prototype.onFailure = function()
        {
          // Add any 401 response handlers here
          return originalOnFailure.apply(this, arguments);
        };
        window.Request._antiForgeryPatched = true;
      }
      // Add Axios antiforgery token interceptor for all non-GET requests
      if (axios && !axios._antiForgeryPatched)
      {
        axios.defaults.headers.common["X-Requested-With"] = "XMLHttpRequest";
        axios.defaults.withCredentials = true;
        if (axiosInterceptorId !== null)
        {
          axios.interceptors.request.eject(axiosInterceptorId);
        }
        axiosInterceptorId = axios.interceptors.request.use((config) =>
        {
          const antiForgeryToken = window.AntiForgeryToken || "";        
          if (antiForgeryToken && config.method && config.method.toUpperCase() !== 'GET')
          {
            config.headers.__RequestVerificationToken = antiForgeryToken;
            console.log(appName + ": Added antiforgery token to axios", config.method.toUpperCase(), config.url);
          }
          else if (config.method && config.method.toUpperCase() !== 'GET')
          {
            console.log(appName + ": No antiforgery token available for axios", config.method.toUpperCase(), config.url);
          }
          return config;
        });
        if (axiosResponseInterceptorId !== null)
        {
          axios.interceptors.response.eject(axiosResponseInterceptorId);
        }
        axiosResponseInterceptorId = axios.interceptors.response.use(
          (resp) =>
            {
              return resp;
            },
            (err) =>
            {
              // Add any 401 response handlers here
              return Promise.reject(err);
            }
        );
        axios._antiForgeryPatched = true;
      }
      // Add XMLHttpRequest interceptor that adds antiforgery token for non-GET requests
      if (window.XMLHttpRequest && !window.XMLHttpRequest._antiForgeryPatched)
      {
        var originalOpen = XMLHttpRequest.prototype.open;
        var originalSend = XMLHttpRequest.prototype.send;
        var originalSetRequestHeader = XMLHttpRequest.prototype.setRequestHeader;
        XMLHttpRequest.prototype.open = function(method, url, async, user, password)
        {
          this._method = method ? method.toUpperCase() : 'GET';
          this._url = url;
          return originalOpen.call(this, method, url, async, user, password);
        };
        XMLHttpRequest.prototype.setRequestHeader = function(header, value)
        {
          this._hasCustomHeaders = true;
          return originalSetRequestHeader.call(this, header, value);
        };
        XMLHttpRequest.prototype.send = function(data)
        {
          if (!this._hasCustomHeaders)
          {
            this.setRequestHeader('X-Requested-With', 'XMLHttpRequest');
          }
          this.withCredentials = true;
          var antiForgeryToken = window.AntiForgeryToken || "";
          if (antiForgeryToken && this._method && this._method !== 'GET')
          {
            this.setRequestHeader('__RequestVerificationToken', antiForgeryToken);
            console.log(appName + ": Added antiforgery token to XMLHttpRequest", this._method, this._url);
          }
          else if (this._method && this._method !== 'GET')
          {
            console.log(appName + ": No antiforgery token available for XMLHttpRequest", this._method, this._url);
          }
          return originalSend.call(this, data);
        };
        // Add XMLHttpRequest response interceptor
        var originalOnReadyStateChange = XMLHttpRequest.prototype.onreadystatechange;
        XMLHttpRequest.prototype.onreadystatechange = function(event)
        {
          if (this.readyState === 4)
          {
            // Add any 401 response handlers here
          }
          if (originalOnReadyStateChange)
          {
            // Create a proper event object if one wasn't provided
            var readyStateEvent = event || new Event('readystatechange');
            originalOnReadyStateChange.call(this, readyStateEvent);
          }
        };
        window.XMLHttpRequest._antiForgeryPatched = true;
      }
      // Add Fetch interceptor that adds antiforgery token for non-GET requests
      if (window.fetch && !window.fetch._antiForgeryPatched)
      {
        originalFetch = window.fetch;
        window.fetch = function(url, options = {})
        {
          options.headers = options.headers || {};
          options.headers['X-Requested-With'] = 'XMLHttpRequest';
          options.credentials = options.credentials || 'include';
          const method = (options.method || 'GET').toUpperCase();
          const antiForgeryToken = window.AntiForgeryToken || "";
          if (antiForgeryToken && method !== 'GET')
          {
            options.headers['__RequestVerificationToken'] = antiForgeryToken;
            console.log(appName + ": Added antiforgery token to fetch", method.toUpperCase(), url);
          }
          else if (method !== 'GET')
          {
            console.log(appName + ": No antiforgery token available for fetch", method.toUpperCase(), url);
          }
          return originalFetch(url, options).then(function(response)
          {
            // Add any 401 response handlers here
            return response;
          }).catch(function(error)
          {
            // Add any 401 response handlers here
            throw error;
          });
        };
        window.fetch._antiForgeryPatched = true;
      }
    }
    // Refresh antiforgery token
    var refreshAntiForgeryToken = function ()
    {
      var xhr = new XMLHttpRequest();
      return new Promise(function (resolve, reject)
      {
        xhr.open('GET', '/RefreshToken', true);
        xhr.onreadystatechange = function ()
        {
          if (xhr.readyState === 4)
          {
            if (xhr.status === 200)
            {
              try
              {
                var data = JSON.parse(xhr.responseText);
                if (data && data.token)
                {
                  window.AntiForgeryToken = data.token;
                  console.log(appName + ": Antiforgery token refreshed successfully");
                  setupInterceptors();
                  resolve(data.token);
                }
                else
                {
                  reject(new Error(appName + ": Invalid antiforgery token refresh response"));
                }
              }
              catch (e)
              {
                reject(e);
              }
            }
            else
            {
              reject(new Error(appName + ": Failed to refresh antiforgery token, status: " + xhr.status));
            }
          }
        };
        xhr.send();
      });
    }
    if (window.AntiForgeryToken)
    {
      console.log(appName + ": Initial antiforgery token set.");
      setupInterceptors();
      clearInterval(window._antiTokenRefreshTimer);
      window._antiTokenRefreshTimer = setInterval(function ()
      {
        refreshAntiForgeryToken();
      }, 15 * 60 * 1000);
    }
    else
    {
      console.log(appName + ": Initial antiforgery token is not set. Attempt to get one..");
      refreshAntiForgeryToken()
        .then(function (token)
        {
          clearInterval(window._antiTokenRefreshTimer);
          window._antiTokenRefreshTimer = setInterval(function ()
          {
            refreshAntiForgeryToken();
          }, 15 * 60 * 1000);
        })
        .catch(function (error)
        {
          console.error(appName + ": Failed to get initial antiforgery token:", error);
          clearInterval(window._antiTokenRefreshTimer);
          window._antiTokenRefreshTimer = setInterval(function ()
          {
            refreshAntiForgeryToken();
          }, 15 * 60 * 1000);
        });
    }
})();
// End: Setup antiforgery token interceptors

Vue.component("grid", Grid);
Vue.component("modal", Modal);
Vue.component("tile", Tile);
Vue.component("dashboard", Dashboard);
Vue.component("pager", Pager);

export default Vue;
